using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace Dynamics365TemplateCompareTransfer
{
    internal static class PluginImages
    {
        public const string Small =
            "";

        public const string Big =
            "";
    }

    [Export(typeof(IXrmToolBoxPlugin)),
        ExportMetadata("Name", "Dynamics 365 Template Compare & Transfer"),
        ExportMetadata(
            "Description",
            "Compare and safely transfer Word and Excel document templates between Dataverse environments."),
        ExportMetadata("SmallImageBase64", PluginImages.Small),
        ExportMetadata("BigImageBase64", PluginImages.Big),
        ExportMetadata("BackgroundColor", "DarkSlateGray"),
        ExportMetadata("PrimaryFontColor", "White"),
        ExportMetadata("SecondaryFontColor", "LightGray")]
    public sealed class DocumentsTemplateMoverPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new DocumentsTemplateMoverControl();
        }
    }
}
